let family='Dragodindes', gen=3, selectedName='';
const storeKey='doob-elevage-checklist-v1'; let checked={},storageOK=true; try{localStorage.setItem(storeKey+'-test','1');localStorage.removeItem(storeKey+'-test');checked=JSON.parse(localStorage.getItem(storeKey)||'{}')||{}}catch(e){checked={};storageOK=false}; const key=n=>family+'|'+n.gen+'|'+n.name; const persist=()=>{try{localStorage.setItem(storeKey,JSON.stringify(checked))}catch(e){storageOK=false}};
const input=document.querySelector('#search'), gens=document.querySelector('#gens'), results=document.querySelector('#results');
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const normalize=s=>s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
function displayGens(){gens.innerHTML=['Toutes',...Array.from({length:10},(_,i)=>i+1)].map(g=>`<button type="button" data-gen="${g==='Toutes'?0:g}" aria-pressed="${(g==='Toutes'?0:g)===gen}">${g==='Toutes'?'Toutes':'G'+g}</button>`).join('');}
function render(){displayGens();document.querySelectorAll('[data-family]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.family===family)); const q=normalize(input.value.trim()); const done=DATA[family].filter(n=>checked[key(n)]).length;document.querySelector('#progress').textContent=done+' / '+DATA[family].length+' montures cochées pour '+family+(storageOK?' · enregistré sur cet appareil':' · sauvegarde locale indisponible'); const matches=DATA[family].filter(n=>(!document.querySelector('#pending').checked||!checked[key(n)])&&(!gen||n.gen===gen)&&(!q||(selectedName ? normalize(n.name)===normalize(selectedName) : normalize([n.name,...n.pairs.flat()].join(' ')).includes(q)))); document.querySelector('#resulttitle').textContent=family+(gen?' · Génération '+gen:' · Toutes générations');document.querySelector('#count').textContent=matches.length+' monture'+(matches.length>1?'s':'')+' affichée'+(matches.length>1?'s':'');
results.innerHTML=matches.length?matches.map(n=>`<article class="card"><header class="card-head"><span class="genbadge">G${n.gen}</span><div><div class="name">${esc(n.name)}</div><div class="role">${n.gen===1?'Monture de départ':'Monture cible'}</div></div></header><div class="pairs">${n.pairs.length?n.pairs.map((pair,i)=>`<p class="pair-label">${n.pairs.length>1?'Alternative '+(i+1):'Parents possibles'}</p><div class="pair">${pair.map((p,j)=>`${j?'<span class="cross" aria-hidden="true">×</span>':''}<button type="button" class="parent" data-parent="${esc(p.replace(/\s*\(G\d+\)$/,''))}" aria-label="Voir le parcours de ${esc(p)}">${esc(p)}</button>`).join('')}</div>`).join(''):'<p class="capture">Capture sauvage : point de départ de ce parcours.</p>'}${n.next.length?`<p class="next">Peut aider à préparer : ${esc(n.next.slice(0,4).join(' · '))}${n.next.length>4?'…':''}</p>`:''}</div><div class="card-check"><label class="tracking"><input type="checkbox" data-check="${esc(n.name)}" data-gen="${n.gen}" ${checked[key(n)]?'checked':''}> ${n.gen===1?'Capture validée':'Naissance validée'}</label></div></article>`).join(''):'<div class="empty">Aucun résultat pour ces filtres. Essaie une autre génération ou réinitialise la recherche.</div>';}
document.querySelector('.family').addEventListener('click',e=>{const b=e.target.closest('[data-family]');if(!b)return;family=b.dataset.family;input.value='';selectedName='';render()});gens.addEventListener('click',e=>{const b=e.target.closest('[data-gen]');if(!b)return;gen=+b.dataset.gen;render()});input.addEventListener('input',()=>{selectedName='';render()});document.querySelector('#pending').addEventListener('change',render);results.addEventListener('change',e=>{if(!e.target.matches('[data-check]'))return;checked[family+'|'+e.target.dataset.gen+'|'+e.target.dataset.check]=e.target.checked;persist();render()});results.addEventListener('click',e=>{const b=e.target.closest('[data-parent]');if(!b)return;gen=0;input.value=b.dataset.parent;selectedName=b.dataset.parent;document.querySelector('#pending').checked=false;render();document.querySelector('#resulttitle').scrollIntoView({behavior:'smooth',block:'start'})});document.querySelector('#reset').addEventListener('click',()=>{gen=0;input.value='';selectedName='';render()});render();